create temporary table batch_input as select * from jsonb_to_recordset($data$[{"available": true, "details": "\nHighlights\nMade by NinaJiaStudio\nMaterials: Polyester\n\nA delicate ivory jacquard tote featuring soft lavender-purple florals, fresh green botanical details, and small butterfly motifs.\nCompared with a traditional floral handbag, this design has a lighter, more romantic character. The combination of pale ivory, lavender and soft green creates a fresh spring-inspired palette, while the woven jacquard surface gives the pattern a subtle texture and elegant finish.\nThe clean rectangular silhouette and long double handles make it an easy everyday shoulder bag. Its understated botanical design pairs beautifully with linen, dresses, cardigans and neutral everyday outfits.\n\nPRODUCT DETAILS\n- Color: Ivory / Lavender Purple / Soft Green\n- Exterior: Woven jacquard fabric\n- Lining: Canvas\n- Pattern: Botanical floral & butterfly motif\n- Closure: Magnetic closure\n- Interior: 1 slip pocket + 1 zip pocket\n- Carry Style: Shoulder carry / hand carry\n- Shape: Rectangular tote\n- Style: Botanical / Chinese-inspired / Romantic\n\nSIZE\n- Bag width: approx. 32 cm / 12.6 in\n- Bag height: approx. 32 cm / 12.6 in\n- Shoulder strap length: approx. 60 cm / 23.6 in\nPlease allow slight measurement differences due to manual measuring.\n\nDESIGN\nThe ivory woven surface is decorated with softly shimmering floral motifs that become especially beautiful under natural light. Rather than a heavily structured handbag, this design has a relaxed silhouette that naturally drapes when carried.\nThe neutral cream-and-gold palette makes it easy to pair with linen, knitwear, dresses, neutral outfits, and simple everyday looks.\n\nPLEASE NOTE\nColors may appear slightly different depending on lighting and screen settings. The placement of the woven floral pattern may also vary slightly from bag to bag.\n\nLess\n", "images": [{"alt": "May include: A cream-colored tote bag featuring a repeating pattern of purple flowers with green stems and small yellow butterflies. The bag has two long, thin, cream-colored shoulder straps and a rectangular shape, constructed from a smooth fabric.", "src": "https://i.etsystatic.com/61131894/r/il/c12d85/8600629984/il_1588xN.8600629984_aj9k.jpg"}, {"alt": "May include: A cream-colored tote bag featuring an embroidered pattern of purple and light green flowers and butterflies. The bag has two matching cream-colored shoulder straps attached to the top edge, with visible stitching along the seams.", "src": "https://i.etsystatic.com/61131894/r/il/49127c/8600630866/il_794xN.8600630866_8wc9.jpg"}], "shops": [{"text": "NinaJiaStudio", "url": "https://www.etsy.com/shop/NinaJiaStudio?ref=shop-header-name&listing_id=4585549341&from_page=listing"}, {"text": "NinaJiaStudio", "url": "https://www.etsy.com/shop/NinaJiaStudio"}], "title": "Floral Jacquard Tote Bag, Purple Botanical Shoulder Bag, Chinese Inspired Woven Handbag", "source_url": "https://www.etsy.com/listing/4585549341/floral-jacquard-tote-bag-purple", "checked_at": "2026-10-13T05:26:33.964Z", "account": "P5", "shop": "NinaJiaStudio", "image_check": {"http_status": 200, "size": [1588, 1588], "sha256": "4156edc4bc76891836841f7310ff04598e618369dd8946275e7f1c5fa6b3b0a2"}, "listing_id": "4585549341", "new_title": "Lavender Floral Jacquard Tote", "body": "Purple flowers, green stems and small butterfly motifs decorate this ivory tote from NinaJiaStudio. Long handles and a rectangular silhouette complete the design. See the original Etsy listing for dimensions and details.", "facebook_draft": "Lavender Floral Jacquard Tote \u2014 Purple flowers, green stems and small butterfly motifs decorate this ivory tote from NinaJiaStudio. Long handles and a rectangular silhouette complete the design. See the original Etsy listing for dimensions and details. Browse: https://www.etsy.com/listing/4585549341/floral-jacquard-tote-bag-purple", "image_url": "https://i.etsystatic.com/61131894/r/il/c12d85/8600629984/il_1588xN.8600629984_aj9k.jpg", "visual_verified": true, "unresolved_reason": null, "board_id": "713820678377803445", "board_name": "Fashion", "category": "Textile Bags", "board_inspection_run": "38351030470"}, {"available": true, "details": "\nHighlights\nMade by NinaJiaStudio\nMaterials: Polyester\n\nA softly structured shoulder bag featuring an elegant ivory jacquard fabric with delicate floral motifs woven in subtle gold and cream tones.\nThe relaxed hobo silhouette gives the bag an effortless, graceful shape, while the floral woven texture adds a distinctive Chinese-inspired touch. Finished with a clean shoulder strap and gold-tone hardware, it works beautifully with both everyday outfits and more refined looks.\nThe spacious interior is designed to carry everyday essentials such as your phone, lipstick, keys, earphones, and other small personal items.\n\nPRODUCT DETAILS\n- Color: Ivory / Cream\n- Exterior: Woven jacquard fabric\n- Lining: Canvas\n- Closure: Magnetic closure\n- Interior: 1 slip pocket + 1 zip pocket\n- Carrying style: Shoulder carry / hand carry\n- Hardware: Gold-tone\n- Style: Hobo / shoulder bag\n- Pattern: Floral jacquard\n\nSIZE\n- Bag width: approx. 32 cm / 12.6 in\n- Bag height: approx. 32 cm / 12.6 in\n- Shoulder strap length: approx. 60 cm / 23.6 in\nPlease allow slight measurement differences due to manual measuring.\n\nDESIGN\nThe ivory woven surface is decorated with softly shimmering floral motifs that become especially beautiful under natural light. Rather than a heavily structured handbag, this design has a relaxed silhouette that naturally drapes when carried.\nThe neutral cream-and-gold palette makes it easy to pair with linen, knitwear, dresses, neutral outfits, and simple everyday looks.\n\nPLEASE NOTE\nColors may appear slightly different depending on lighting and screen settings. The placement of the woven floral pattern may also vary slightly from bag to bag.\n\nLess\n", "images": [{"alt": "May include: A champagne-colored hobo bag featuring an embroidered floral pattern in gold and white thread. The bag has a single, long, white tubular shoulder strap attached with gold-toned metal hardware, creating a triangular silhouette.", "src": "https://i.etsystatic.com/61131894/r/il/196d3a/8600466340/il_1588xN.8600466340_7h9s.jpg"}, {"alt": "May include: A cream-colored hobo bag featuring an intricate embroidered pattern of white and gold chrysanthemum flowers. The bag has a smooth, satin-like finish and is attached to a gold-toned metal chain strap connected by matching cream-colored tabs.", "src": "https://i.etsystatic.com/61131894/r/il/0b2c31/8648255521/il_794xN.8648255521_58c8.jpg"}], "shops": [{"text": "NinaJiaStudio", "url": "https://www.etsy.com/shop/NinaJiaStudio?ref=shop-header-name&listing_id=4585524379&from_page=listing"}, {"text": "NinaJiaStudio", "url": "https://www.etsy.com/shop/NinaJiaStudio"}], "title": "Floral Jacquard Hobo Bag, Chinese Inspired Shoulder Bag, Woven Brocade Handbag", "source_url": "https://www.etsy.com/listing/4585524379/floral-jacquard-hobo-bag-chinese", "checked_at": "2026-10-13T05:26:41.581Z", "account": "P5", "shop": "NinaJiaStudio", "image_check": {"http_status": 200, "size": [1588, 1588], "sha256": "513944bfa75eac5c9d7d78f2ad59c52119660d23e2846959a5715b7f6687192f"}, "listing_id": "4585524379", "new_title": "Ivory Floral Jacquard Shoulder Bag", "body": "An ivory floral jacquard surface and a relaxed hobo shape define this NinaJiaStudio shoulder bag. A slim strap and gold-tone fittings finish the look. Explore details on Etsy.", "facebook_draft": "Ivory Floral Jacquard Shoulder Bag \u2014 An ivory floral jacquard surface and a relaxed hobo shape define this NinaJiaStudio shoulder bag. A slim strap and gold-tone fittings finish the look. Explore details on Etsy. Browse: https://www.etsy.com/listing/4585524379/floral-jacquard-hobo-bag-chinese", "image_url": "https://i.etsystatic.com/61131894/r/il/196d3a/8600466340/il_1588xN.8600466340_7h9s.jpg", "visual_verified": true, "unresolved_reason": null, "board_id": "713820678377803445", "board_name": "Fashion", "category": "Textile Bags", "board_inspection_run": "38351030470"}, {"available": true, "details": "\nHighlights\nMade by NinaJiaStudio\nMaterials: Polyester\n\nRetro green brocade fabric printed with traditional Chinese fortune \"Fa\" character motif, symbolizing good fortune. Secure zipper closure with one inner patch pocket for divided storage. Matched with brown faux\u2011leather strap connected by metal rings, strap length approx 45cm. Roomy interior fits iPad 11, water bottle, umbrella, 2\u20113 books. Slouchy hobo silhouette, fun new\u2011Chinese aesthetic, great for commute, school and daily shopping.\n\n**Product Information**\nOuter fabric: Brocade jacquard fabric, green base with Chinese fortune \"Fa\" character pattern.\nClosure: Top zipper closure for better security.\nInterior structure: One inner patch pocket.\nStrap: Brown faux\u2011leather strap attached with metal rings, strap length about 45cm (excluding rings).\nMeasurements: Width approx 29cm, height approx 26cm, side depth 6cm. Minor tolerance for manual measurement.\nCapacity: Fits iPad 11, water bottle, umbrella, phone, keys, 2\u20113 size\u201116 books and daily essentials.\nFeatures: Lucky Chinese\u2011character print, secure zipper, slouchy hobo shape, large storage, retro fun colorway.\nApplication: Daily commute, school, shopping trips, matches new\u2011Chinese\u2011style and casual vintage outfits.\n\nLess\n", "images": [{"alt": "May include: A green tote bag featuring a repeating dark brown grid pattern with the Chinese character for prosperity, \"Fa,\" in each square. The bag has two light brown leather-like shoulder straps attached with gold-toned metal rings.", "src": "https://i.etsystatic.com/61131894/r/il/e0b2ef/8531433415/il_1588xN.8531433415_rxqk.jpg"}, {"alt": "May include: A green fabric bag featuring a dark brown grid pattern with repeating Chinese characters within each square. The bag is constructed with a textured material and includes a metallic gold ring attachment connected to a brown leather strap.", "src": "https://i.etsystatic.com/61131894/r/il/213d71/8531433519/il_1588xN.8531433519_oblv.jpg"}], "shops": [{"text": "NinaJiaStudio", "url": "https://www.etsy.com/shop/NinaJiaStudio?ref=shop-header-name&listing_id=4569933203&from_page=listing"}, {"text": "NinaJiaStudio", "url": "https://www.etsy.com/shop/NinaJiaStudio"}], "title": "Chinese Fortune\u2011Character Brocade Hobo Bag, Green Oriental Fabric Tote", "source_url": "https://www.etsy.com/listing/4569933203/chinese-fortunecharacter-brocade-hobo", "checked_at": "2026-10-13T05:26:59.700Z", "account": "P5", "shop": "NinaJiaStudio", "image_check": {"http_status": 200, "size": [1588, 1589], "sha256": "a4ecc1c2578efd4f69a6978c917146290332d0b2985c719fe18267c6b78eb4ad"}, "listing_id": "4569933203", "new_title": "Green Character-Pattern Shoulder Bag", "body": "A dark character-and-grid pattern stands out on this green fabric shoulder bag from NinaJiaStudio. A brown faux-leather strap completes the design. View the original Etsy listing for dimensions and details.", "facebook_draft": "Green Character-Pattern Shoulder Bag \u2014 A dark character-and-grid pattern stands out on this green fabric shoulder bag from NinaJiaStudio. A brown faux-leather strap completes the design. View the original Etsy listing for dimensions and details. Browse: https://www.etsy.com/listing/4569933203/chinese-fortunecharacter-brocade-hobo", "image_url": "https://i.etsystatic.com/61131894/r/il/e0b2ef/8531433415/il_1588xN.8531433415_rxqk.jpg", "visual_verified": true, "unresolved_reason": null, "board_id": "713820678377803445", "board_name": "Fashion", "category": "Textile Bags", "board_inspection_run": "38351030470"}, {"available": true, "details": "\nHighlights\nMade by NinaJiaStudio\n\nBring timeless oriental elegance to your everyday style with this Chinese-inspired corduroy tote bag. Featuring a delicate bamboo leaf embossed pattern, this bag combines traditional aesthetic elements with a modern minimalist silhouette.\n\nMade with soft textured corduroy fabric, this large-capacity tote offers plenty of space for daily essentials such as your phone, wallet, cosmetics, books, and small accessories. The comfortable long handle design allows it to be carried as a shoulder bag or handbag, making it perfect for everyday use, shopping, work, travel, and casual outings.\n\nInspired by traditional Chinese botanical motifs, the bamboo leaf design symbolizes natural beauty and simplicity. The warm texture and vintage color palette make this bag a stylish accessory for autumn and winter outfits.\n\nProduct Details:\nOuter fabric: Corduroy fabric with embossed bamboo\u2011leaf texture.\nStrap: Long faux\u2011leather shoulder strap for single\u2011shoulder carry.\nShape: Slouchy open\u2011top tote bag, soft foldable body.\nFeatures: Vintage tea\u2011brown tone, embossed bamboo leaf pattern, large capacity, soft comfortable fabric.\nCapacity: Fits books, tablet, umbrella, water bottle and other large daily belongings.\nApplication: Daily commute, school, shopping & travel, matches log\u2011cabin, muted\u2011tone and new\u2011Chinese\u2011style outfits.\n\n\nPlease Note:\n\nAll measurements are taken by hand, please allow a 1-4 cm difference.\nDue to different lighting conditions and monitor settings, the actual color may slightly vary from the photos.\nEach handmade item may have slight variations, making every piece unique.\nNo returns or exchanges.\n\nFor more choices, please feel free to browse our shop and discover more beautiful designs.\nhttps://www.etsy.com/shop/NinaJiaStudio?ref=dashboard-header\n\nLess\n", "images": [{"alt": "May include: A brown fabric tote bag featuring a light-colored bamboo leaf pattern throughout. The bag includes two long, smooth, brown leather-like shoulder straps attached to the top edge, providing a structured yet flexible carry option.", "src": "https://i.etsystatic.com/61131894/r/il/c50838/8483396918/il_1588xN.8483396918_i2ix.jpg"}, {"alt": "May include: A tote bag made of olive green fabric with a white botanical leaf print pattern. The bag features two long, smooth, reddish-brown leather-like handles attached to the top edge, providing a contrast to the textured, earthy-toned body.", "src": "https://i.etsystatic.com/61131894/r/il/dbb077/8483395544/il_794xN.8483395544_7kgh.jpg"}], "shops": [{"text": "NinaJiaStudio", "url": "https://www.etsy.com/shop/NinaJiaStudio?ref=shop-header-name&listing_id=4558515139&from_page=listing"}, {"text": "NinaJiaStudio", "url": "https://www.etsy.com/shop/NinaJiaStudio"}], "title": "Vintage Bamboo\u2011Leaf Embossed Corduroy Tote Bag, Brown Fabric Shoulder Bag", "source_url": "https://www.etsy.com/listing/4558515139/vintage-bambooleaf-embossed-corduroy", "checked_at": "2026-10-13T05:27:07.314Z", "account": "P5", "shop": "NinaJiaStudio", "image_check": {"http_status": 200, "size": [1588, 1589], "sha256": "03967a6c41c6d41da220d3cfd784bbe4f23f345603f99eb01d502b443087ad59"}, "listing_id": "4558515139", "new_title": "Brown Bamboo-Leaf Tote Bag", "body": "Bamboo-leaf motifs add texture to this brown fabric tote from NinaJiaStudio, finished with long brown handles. A botanical accent for everyday outfits. See details on Etsy.", "facebook_draft": "Brown Bamboo-Leaf Tote Bag \u2014 Bamboo-leaf motifs add texture to this brown fabric tote from NinaJiaStudio, finished with long brown handles. A botanical accent for everyday outfits. See details on Etsy. Browse: https://www.etsy.com/listing/4558515139/vintage-bambooleaf-embossed-corduroy", "image_url": "https://i.etsystatic.com/61131894/r/il/c50838/8483396918/il_1588xN.8483396918_i2ix.jpg", "visual_verified": true, "unresolved_reason": null, "board_id": "713820678377803445", "board_name": "Fashion", "category": "Textile Bags", "board_inspection_run": "38351030470"}, {"available": true, "details": "\nHighlights\nMaterials: Polyester\n\nElegant black satin\u2011fabric hobo shoulder bag decorated with golden\u2011thread embroidery of plum blossoms, bamboo, birds and butterflies, full of retro oriental charm. It features curved brown faux\u2011leather strap and golden metal hardware. Slouchy silhouette offers ample room for tablet, books and daily essentials. Sophisticated match for new\u2011Chinese\u2011style outfits, great for commuting, shopping and outings.\n\n**Product Information**\nOuter fabric: Jacquard fabric with golden bird\u2011butterfly\u2011plum\u2011bamboo pattern on black base.\nLining material: Canvas.\nClosure: Magnetic snap.\nInterior structure: 1 patch pocket, 1 zipper pocket.\nCarry ways: Hand\u2011held, shoulder carry.\nCapacity: Fits phone, lipstick, keys, earbuds and other small daily belongings.\nFeatures: Retro oriental jacquard pattern, divided storage, compact and practical.\nApplication: Daily outings, short\u2011distance commuting, matches new\u2011Chinese\u2011style and vintage outfits.\n\nLess\n", "images": [{"alt": "May include: A black hobo bag featuring a white floral and butterfly print with a bird perched on a branch. The bag has a single brown leather handle attached with gold-toned metal hardware, creating a structured yet slouchy silhouette.", "src": "https://i.etsystatic.com/61131894/r/il/54856b/8475291178/il_1588xN.8475291178_rmrg.jpg"}, {"alt": "May include: A black hobo bag featuring intricate gold-toned embroidery of butterflies, floral branches, and leaves. The bag includes a gold-toned metal hardware connector on the strap and detailed close-up circular insets showing the embroidery.", "src": "https://i.etsystatic.com/61131894/r/il/ef1719/8523192841/il_794xN.8523192841_4gz3.jpg"}], "shops": [{"text": "NinaJiaStudio", "url": "https://www.etsy.com/shop/NinaJiaStudio?ref=shop-header-name&listing_id=4568703716&from_page=listing"}, {"text": "", "url": "https://www.etsy.com/shop/NinaJiaStudio?ref=l2-about-shopname&from_page=listing"}], "title": "New Chinese Bird\u2011Butterfly Embroidered Hobo Bag, Satin Fabric Shoulder Purse", "source_url": "https://www.etsy.com/listing/4568703716/new-chinese-birdbutterfly-embroidered", "checked_at": "2026-10-13T05:27:14.527Z", "account": "P5", "shop": "NinaJiaStudio", "image_check": {"http_status": 200, "size": [1588, 1588], "sha256": "291a4db9d2bcf829c3299cf0820b07584e68b82ce31009a20878aa80b6f02f2b"}, "listing_id": "4568703716", "new_title": "Black Bird and Butterfly Shoulder Bag", "body": "Birds, butterflies and botanical motifs decorate this black shoulder bag from NinaJiaStudio. A curved brown handle and gold-tone fittings complement the relaxed silhouette. Explore the original listing on Etsy.", "facebook_draft": "Black Bird and Butterfly Shoulder Bag \u2014 Birds, butterflies and botanical motifs decorate this black shoulder bag from NinaJiaStudio. A curved brown handle and gold-tone fittings complement the relaxed silhouette. Explore the original listing on Etsy. Browse: https://www.etsy.com/listing/4568703716/new-chinese-birdbutterfly-embroidered", "image_url": "https://i.etsystatic.com/61131894/r/il/54856b/8475291178/il_1588xN.8475291178_rmrg.jpg", "visual_verified": true, "unresolved_reason": null, "board_id": "713820678377803445", "board_name": "Fashion", "category": "Textile Bags", "board_inspection_run": "38351030470"}]$data$::jsonb) x(shop text,listing_id text,source_url text,category text,board_id text,new_title text,body text,image_url text,checked_at timestamptz,facebook_draft text);
do $$ begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard required'; end if;
 if exists(select 1 from batch_input where checked_at<now()-interval '24 hours' or checked_at>now()) then raise exception 'Verification expired'; end if;
 if (select count(*) from batch_input x join shops s on s.shop_name=x.shop and s.status='active' join shop_social_accounts m on m.shop_id=s.id and m.active and m.platform='pinterest' join social_accounts a on a.id=m.social_account_id and a.handle='ivy5205' and a.active and a.platform='pinterest' join pinterest_oauth_credentials cr on cr.social_account_id=a.id and lower(cr.pinterest_username)='ivy5205')<>5 then raise exception 'P5 routing or authorization changed'; end if;
end $$;
-- Report prior records before inserting; only genuinely new products enter this batch.
select json_build_object('preexisting_listing',p.etsy_listing_id,'history_count',(select count(*) from publish_history h where h.product_id=p.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id;
create temporary table new_products(id uuid,shop_id uuid,etsy_listing_id text);
with ins as (
 insert into products(shop_id,etsy_listing_id,etsy_url,title,category,listing_status,primary_image_url,original_image_urls,source_payload,source_discovered_at,last_seen_at)
 select s.id,x.listing_id,x.source_url,x.new_title,x.category,'active',x.image_url,jsonb_build_array(x.image_url),jsonb_build_object('verified_at',x.checked_at,'source',x.source_url,'image_verified',true,'batch','seven-day-20261013-2'),x.checked_at,x.checked_at from batch_input x join shops s on s.shop_name=x.shop
 where not exists(select 1 from products p where p.etsy_listing_id=x.listing_id)
 on conflict(shop_id,etsy_listing_id) do nothing returning id,shop_id,etsy_listing_id
) insert into new_products select * from ins;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'pinterest','verified-original-20261013',x.image_url,x.new_title,x.body,x.source_url,x.category,'product','ready' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'facebook','verified-original-20261013',x.image_url,x.new_title,x.facebook_draft,x.source_url,x.category,'product','draft' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into publish_queue(shop_id,product_id,content_variant_id,platform,social_account_id,status)
select p.shop_id,p.id,cv.id,'pinterest',a.id,'ready' from new_products p join content_variants cv on cv.product_id=p.id and cv.platform='pinterest' join social_accounts a on a.handle='ivy5205' and a.platform='pinterest';
insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select q.id,x.board_id,pinterest_publish_snapshot(q.id),x.checked_at,x.source_url from new_products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest';
select json_build_object('listing_id',p.etsy_listing_id,'queue_id',q.id,'status',q.status,'board_id',r.board_id,'snapshot_matches',r.snapshot=pinterest_publish_snapshot(q.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest' join pinterest_publish_reviews r on r.queue_id=q.id;
commit;
